import stripe
from langchain_core.tools import tool


def _clear_pending_items(customer_id: str) -> None:
    # Remove leftover pending invoice items so they are not billed again on the next invoice
    pending = stripe.InvoiceItem.list(customer=customer_id, pending=True, limit=100)
    for ii in pending['data']:
        stripe.InvoiceItem.delete(ii['id'])


@tool
def preview_and_charge_proration(subscription_id: str, new_price_id: str) -> dict:
    sub = stripe.Subscription.retrieve(subscription_id)
    item = sub['items']['data'][0]
    upcoming = stripe.Invoice.upcoming(customer=sub['customer'], subscription=subscription_id, subscription_items=[{'id': item['id'], 'price': new_price_id}])
    amount = sum((l['amount'] for l in upcoming['lines']['data'] if l.get('proration')))
    result = {'subscription_id': subscription_id, 'current_plan': item['price']['id'], 'proration_amount': amount, 'currency': upcoming['currency']}
    if amount > 0:
        intent = stripe.PaymentIntent.create(amount=amount, currency=upcoming['currency'], customer=sub['customer'], off_session=True, confirm=True, description='Plan change proration')
        result['payment_intent'] = intent['id']
        result['status'] = intent['status']
        _clear_pending_items(sub['customer'])
    else:
        result['status'] = 'no_charge'
    return result
